const EASE = "cubic-bezier(0.2, 0, 0, 1)";

/* ------------------------------ types ------------------------------ */

type Vehicle = { id: string; name: string; payloadLEO: number; payloadTLI: number; cost: number; note: string; source: string };
type Orbit = { id: string; name: string; spec: string; reserve: number; downlinkMod: number; scienceMod: number; cost: number; note: string; source: string };
type Power = { id: string; name: string; mass: number; output: number; cost: number; lifespan: string; source: string };
type Instrument = { id: string; name: string; abbr: string; mass: number; power: number; kbps: number; cost: number; science: number; desc: string; source: string };
type Mission = {
  id: string;
  name: string;
  objective: string;
  difficulty: "EASY" | "MEDIUM" | "HARD" | "SANDBOX";
  duration: string;
  days: number;
  science: number;
  budget: number;
  downlink: number;
  regime: "leo" | "beyond";
  analogues: string;
};
type SectionKey = "vehicle" | "orbit" | "power" | "instruments";
type CrewMember = { id: string; name: string; tag: string; perk: string; color: string; owns: SectionKey[] };
type Mode = "solo" | "coop" | "versus";
type Difficulty = "rookie" | "standard" | "veteran";
type TeamMember = { id: string; name: string; roleId: string; avatar: number };
type VersusTeam = { id: string; name: string; avatar: number };
type VersusResult = { teamId: string; ok: boolean; score: number; budget: number; mass: number; massMargin: number; config: string; code: string; grade: string };
type LogEntry = { id: string; who: string; avatar: number; color: string; text: string };
type SimEvent = { id: string; text: string; delta: number };
type Shock = { id: string; text: string; short: string; cap: "mass" | "power" | "budget" | "data"; mult: number };
type SavedRun = {
  id: string;
  ts: number;
  team: string;
  missionId: string;
  missionName: string;
  score: number;
  budget: number;
  mass: number;
  config: string;
  avatar: number;
  grade: string;
  difficulty: Difficulty;
  mode: Mode;
  ref?: boolean;
};
type SavedDesign = { id: string; name: string; ts: number; code: string };
type V3 = [number, number, number];

