/* ------------------------------ persistence ------------------------------ */

function loadRuns(): SavedRun[] {
  try {
    const raw = localStorage.getItem("ma-runs");
    return raw ? (JSON.parse(raw) as SavedRun[]) : [];
  } catch {
    return [];
  }
}
function persistRuns(runs: SavedRun[]) {
  try {
    localStorage.setItem("ma-runs", JSON.stringify(runs.slice(0, 50)));
  } catch {
    /* storage unavailable */
  }
}
function loadDesigns(): SavedDesign[] {
  try {
    const raw = localStorage.getItem("ma-designs");
    return raw ? (JSON.parse(raw) as SavedDesign[]) : [];
  } catch {
    return [];
  }
}
function persistDesigns(ds: SavedDesign[]) {
  try {
    localStorage.setItem("ma-designs", JSON.stringify(ds.slice(0, 30)));
  } catch {
    /* storage unavailable */
  }
}
function readBest(missionId: string): number {
  try {
    const v = localStorage.getItem("ma-best-" + missionId);
    return v ? parseInt(v, 10) || 0 : 0;
  } catch {
    return 0;
  }
}
function writeBest(missionId: string, score: number) {
  try {
    localStorage.setItem("ma-best-" + missionId, String(score));
  } catch {
    /* storage unavailable */
  }
}

/* ------------------------------ state ------------------------------ */

type Screen = "select" | "bench" | "results" | "versus";

type State = {
  screen: Screen;
  mode: Mode;
  difficulty: Difficulty;
  missionId: string | null;
  vehicleId: string | null;
  orbitId: string | null;
  powerId: string | null;
  instrumentIds: string[];
  teamName: string;
  teamMembers: TeamMember[];
  activeSeat: string | null;
  strict: boolean;
  goVotes: string[];
  pilotName: string;
  pilotAvatar: number;
  versusTeams: VersusTeam[];
  versusIdx: number;
  versusResults: VersusResult[];
  log: LogEntry[];
};

type Action =
  | { type: "SELECT_MISSION"; id: string }
  | { type: "SET_SCREEN"; screen: Screen }
  | { type: "SET_MODE"; mode: Mode }
  | { type: "SET_DIFFICULTY"; difficulty: Difficulty }
  | { type: "SELECT_VEHICLE"; id: string }
  | { type: "SELECT_ORBIT"; id: string }
  | { type: "SELECT_POWER"; id: string }
  | { type: "TOGGLE_INSTRUMENT"; id: string }
  | { type: "ADD_MEMBER" }
  | { type: "REMOVE_MEMBER"; id: string }
  | { type: "SET_MEMBER_NAME"; id: string; name: string }
  | { type: "SET_MEMBER_ROLE"; id: string; roleId: string }
  | { type: "SET_MEMBER_AVATAR"; id: string; avatar: number }
  | { type: "SET_ACTIVE_SEAT"; id: string }
  | { type: "TOGGLE_STRICT" }
  | { type: "TOGGLE_GO"; id: string }
  | { type: "SET_TEAM_NAME"; name: string }
  | { type: "SET_PILOT"; name?: string; avatar?: number }
  | { type: "SET_VS_NAME"; id: string; name: string }
  | { type: "SET_VS_AVATAR"; id: string; avatar: number }
  | { type: "ADD_VS_TEAM" }
  | { type: "REMOVE_VS_TEAM"; id: string }
  | { type: "SUBMIT_VERSUS"; result: VersusResult }
  | { type: "REMATCH" }
  | { type: "IMPORT_DESIGN"; data: any };

let _uid = 0;
const uid = (p: string) => `${p}${Date.now().toString(36)}${(_uid++).toString(36)}`;

const initialState: State = {
  screen: "select",
  mode: "solo",
  difficulty: "standard",
  missionId: null,
  vehicleId: null,
  orbitId: null,
  powerId: null,
  instrumentIds: [],
  teamName: "",
  teamMembers: [],
  activeSeat: null,
  strict: true,
  goVotes: [],
  pilotName: "Pilot",
  pilotAvatar: 0,
  versusTeams: [
    { id: "vt1", name: "Team Alpha", avatar: 0 },
    { id: "vt2", name: "Team Bravo", avatar: 4 },
  ],
  versusIdx: 0,
  versusResults: [],
  log: [],
};

function activeMember(s: State): TeamMember | null {
  return s.teamMembers.find((m) => m.id === s.activeSeat) ?? s.teamMembers[0] ?? null;
}

function actorOf(s: State): { who: string; avatar: number; color: string } {
  if (s.mode === "coop" && s.teamMembers.length > 0) {
    const m = activeMember(s)!;
    const role = CREW.find((c) => c.id === m.roleId) ?? CREW[0];
    return { who: m.name, avatar: m.avatar, color: role.color };
  }
  if (s.mode === "versus") {
    const t = s.versusTeams[s.versusIdx];
    return { who: t?.name ?? "Team", avatar: t?.avatar ?? 0, color: "var(--signal)" };
  }
  return { who: s.pilotName || "Pilot", avatar: s.pilotAvatar, color: "var(--signal)" };
}

function say(s: State, text: string): LogEntry[] {
  const a = actorOf(s);
  return [...s.log, { id: uid("l"), ...a, text }].slice(-40);
}
function sys(s: State, text: string): LogEntry[] {
  return [...s.log, { id: uid("l"), who: "CAPCOM", avatar: -1, color: "var(--text-mid)", text }].slice(-40);
}

function applyDesign(base: State, d: any): State | null {
  if (!d || !MISSIONS.some((m) => m.id === d.m)) return null;
  const maxInst = d.m === "sandbox" ? 6 : 2;
  const members: TeamMember[] = Array.isArray(d.t)
    ? d.t.slice(0, 4).map((t: any, idx: number) => ({
        id: uid("tm"),
        name: String(t?.n ?? `Player ${idx + 1}`).slice(0, 24),
        roleId: CREW.some((c) => c.id === t?.r) ? t.r : CREW[idx % 4].id,
        avatar: Number.isInteger(t?.a) ? ((t.a % AVATARS.length) + AVATARS.length) % AVATARS.length : idx,
      }))
    : [];
  const mode: Mode = ["solo", "coop", "versus"].includes(d.mo) ? d.mo : members.length > 0 ? "coop" : "solo";
  return {
    ...base,
    screen: "bench",
    mode,
    difficulty: DIFFICULTIES.some((x) => x.id === d.d) ? d.d : base.difficulty,
    missionId: d.m,
    vehicleId: VEHICLES.some((v) => v.id === d.v) ? d.v : null,
    orbitId: ORBITS[d.m]?.some((o) => o.id === d.o) ? d.o : null,
    powerId: POWERS.some((p) => p.id === d.p) ? d.p : null,
    instrumentIds: Array.isArray(d.i) ? d.i.filter((id: string) => INSTRUMENTS.some((x) => x.id === id)).slice(0, maxInst) : [],
    teamName: typeof d.tn === "string" ? d.tn.slice(0, 32) : "",
    teamMembers: members,
    activeSeat: members[0]?.id ?? null,
    goVotes: [],
    versusIdx: 0,
    versusResults: [],
    log: [],
  };
}

function encodeDesign(state: State): string {
  const rec = {
    m: state.missionId,
    v: state.vehicleId,
    o: state.orbitId,
    p: state.powerId,
    i: state.instrumentIds,
    d: state.difficulty,
    mo: state.mode,
    tn: state.teamName,
    t: state.teamMembers.map((m) => ({ n: m.name, r: m.roleId, a: m.avatar })),
  };
  try {
    return btoa(unescape(encodeURIComponent(JSON.stringify(rec))));
  } catch {
    return "";
  }
}
function decodeDesign(code: string): any | null {
  try {
    return JSON.parse(decodeURIComponent(escape(atob(code.trim()))));
  } catch {
    return null;
  }
}
function designState(code: string): State | null {
  return applyDesign(initialState, decodeDesign(code));
}

const clearDesign = {
  vehicleId: null,
  orbitId: null,
  powerId: null,
  instrumentIds: [] as string[],
  goVotes: [] as string[],
};

function reducer(s: State, a: Action): State {
  switch (a.type) {
    case "SELECT_MISSION": {
      const m = MISSIONS.find((x) => x.id === a.id);
      const base: State = { ...s, ...clearDesign, screen: "bench", missionId: a.id, versusIdx: 0, versusResults: [], log: [] };
      const diff = DIFFICULTIES.find((x) => x.id === s.difficulty)!;
      return { ...base, log: sys(base, `${m?.name ?? "Mission"} loaded · flight rules ${diff.label}.`) };
    }
    case "SET_SCREEN":
      return { ...s, screen: a.screen };
    case "SET_MODE":
      return { ...s, mode: a.mode, goVotes: [] };
    case "SET_DIFFICULTY":
      return { ...s, difficulty: a.difficulty };
    case "SELECT_VEHICLE": {
      const on = s.vehicleId !== a.id;
      const v = VEHICLES.find((x) => x.id === a.id);
      return { ...s, vehicleId: on ? a.id : null, goVotes: [], log: say(s, on ? `locked in ${v?.name} as launch vehicle.` : `released ${v?.name}.`) };
    }
    case "SELECT_ORBIT": {
      const on = s.orbitId !== a.id;
      const o = s.missionId ? ORBITS[s.missionId]?.find((x) => x.id === a.id) : undefined;
      return { ...s, orbitId: on ? a.id : null, goVotes: [], log: say(s, on ? `selected ${o?.name} route.` : `cleared the ${o?.name} route.`) };
    }
    case "SELECT_POWER": {
      const on = s.powerId !== a.id;
      const p = POWERS.find((x) => x.id === a.id);
      return { ...s, powerId: on ? a.id : null, goVotes: [], log: say(s, on ? `chose ${p?.name} for power.` : `removed ${p?.name}.`) };
    }
    case "TOGGLE_INSTRUMENT": {
      const i = INSTRUMENTS.find((x) => x.id === a.id);
      const has = s.instrumentIds.includes(a.id);
      const max = s.missionId === "sandbox" ? 6 : 2;
      if (has) return { ...s, instrumentIds: s.instrumentIds.filter((x) => x !== a.id), goVotes: [], log: say(s, `unmounted the ${i?.name}.`) };
      if (s.instrumentIds.length >= max) return s;
      return { ...s, instrumentIds: [...s.instrumentIds, a.id], goVotes: [], log: say(s, `mounted the ${i?.name}.`) };
    }
    case "ADD_MEMBER": {
      if (s.teamMembers.length >= 4) return s;
      const takenRoles = new Set(s.teamMembers.map((m) => m.roleId));
      const takenAv = new Set(s.teamMembers.map((m) => m.avatar));
      const role = CREW.find((c) => !takenRoles.has(c.id)) ?? CREW[0];
      const avatar = AVATARS.findIndex((_, idx) => !takenAv.has(idx));
      const id = uid("tm");
      const member: TeamMember = { id, name: `Player ${s.teamMembers.length + 1}`, roleId: role.id, avatar: avatar < 0 ? 0 : avatar };
      const next = { ...s, teamMembers: [...s.teamMembers, member], activeSeat: s.activeSeat ?? id };
      return { ...next, log: sys(next, `${member.name} joined as ${role.name}.`), goVotes: [] };
    }
    case "REMOVE_MEMBER": {
      const rest = s.teamMembers.filter((m) => m.id !== a.id);
      return { ...s, teamMembers: rest, activeSeat: s.activeSeat === a.id ? rest[0]?.id ?? null : s.activeSeat, goVotes: s.goVotes.filter((x) => x !== a.id) };
    }
    case "SET_MEMBER_NAME":
      return { ...s, teamMembers: s.teamMembers.map((m) => (m.id === a.id ? { ...m, name: a.name.slice(0, 24) } : m)) };
    case "SET_MEMBER_ROLE":
      return { ...s, goVotes: [], teamMembers: s.teamMembers.map((m) => (m.id === a.id ? { ...m, roleId: a.roleId } : m)) };
    case "SET_MEMBER_AVATAR":
      return { ...s, teamMembers: s.teamMembers.map((m) => (m.id === a.id ? { ...m, avatar: a.avatar } : m)) };
    case "SET_ACTIVE_SEAT": {
      const m = s.teamMembers.find((x) => x.id === a.id);
      if (!m) return s;
      return { ...s, activeSeat: a.id, log: sys(s, `${m.name} has the console.`) };
    }
    case "TOGGLE_STRICT":
      return { ...s, strict: !s.strict };
    case "TOGGLE_GO": {
      const m = s.teamMembers.find((x) => x.id === a.id);
      const on = s.goVotes.includes(a.id);
      const votes = on ? s.goVotes.filter((x) => x !== a.id) : [...s.goVotes, a.id];
      const role = CREW.find((c) => c.id === m?.roleId);
      return {
        ...s,
        goVotes: votes,
        log: [...s.log, { id: uid("l"), who: m?.name ?? "Station", avatar: m?.avatar ?? -1, color: role?.color ?? "var(--text-mid)", text: on ? `${role?.name ?? "Station"} is on HOLD.` : `${role?.name ?? "Station"} reports GO.` }].slice(-40),
      };
    }
    case "SET_TEAM_NAME":
      return { ...s, teamName: a.name.slice(0, 32) };
    case "SET_PILOT":
      return { ...s, pilotName: a.name !== undefined ? a.name.slice(0, 24) : s.pilotName, pilotAvatar: a.avatar ?? s.pilotAvatar };
    case "SET_VS_NAME":
      return { ...s, versusTeams: s.versusTeams.map((t) => (t.id === a.id ? { ...t, name: a.name.slice(0, 24) } : t)) };
    case "SET_VS_AVATAR":
      return { ...s, versusTeams: s.versusTeams.map((t) => (t.id === a.id ? { ...t, avatar: a.avatar } : t)) };
    case "ADD_VS_TEAM": {
      if (s.versusTeams.length >= 4) return s;
      const names = ["Team Alpha", "Team Bravo", "Team Charlie", "Team Delta"];
      const used = new Set(s.versusTeams.map((t) => t.name));
      const name = names.find((n) => !used.has(n)) ?? `Team ${s.versusTeams.length + 1}`;
      const takenAv = new Set(s.versusTeams.map((t) => t.avatar));
      const avatar = AVATARS.findIndex((_, idx) => !takenAv.has(idx));
      return { ...s, versusTeams: [...s.versusTeams, { id: uid("vt"), name, avatar: avatar < 0 ? 0 : avatar }] };
    }
    case "REMOVE_VS_TEAM":
      if (s.versusTeams.length <= 2) return s;
      return { ...s, versusTeams: s.versusTeams.filter((t) => t.id !== a.id) };
    case "SUBMIT_VERSUS": {
      const results = [...s.versusResults.filter((r) => r.teamId !== a.result.teamId), a.result];
      const nextIdx = s.versusIdx + 1;
      const done = nextIdx >= s.versusTeams.length;
      const next: State = {
        ...s,
        ...clearDesign,
        versusResults: results,
        versusIdx: done ? s.versusIdx : nextIdx,
        screen: done ? "versus" : "bench",
      };
      const team = s.versusTeams[nextIdx];
      return { ...next, log: done ? next.log : sys(next, `${team?.name ?? "Next team"} is on the console.`) };
    }
    case "REMATCH":
      return { ...s, ...clearDesign, versusIdx: 0, versusResults: [], screen: "bench", log: sys(s, "Rematch — all teams reset.") };
    case "IMPORT_DESIGN": {
      const next = applyDesign(s, a.data);
      return next ? { ...next, log: sys(next, "Shared design loaded.") } : s;
    }
    default:
      return s;
  }
}

/* ------------------------------ helpers ------------------------------ */

const fmtInt = (n: number) => Math.round(n).toLocaleString("en-US");
const fmtMoney = (m: number) => `$${Number.isInteger(m) ? m : m.toFixed(1)}M`;
const clamp = (n: number, a: number, b: number) => Math.min(b, Math.max(a, n));
const smooth = (x: number) => {
  const t = clamp(x, 0, 1);
  return t * t * (3 - 2 * t);
};

function sumOf<T>(arr: T[], f: (x: T) => number): number {
  return arr.reduce((a, x) => a + f(x), 0);
}

function useAnimatedNumber(target: number, duration = 200): number {
  const reduced = useReducedMotion();
  const [val, setVal] = useState(target);
  const fromRef = useRef(target);
  useEffect(() => {
    if (reduced) {
      fromRef.current = target;
      setVal(target);
      return;
    }
    const from = fromRef.current;
    if (from === target) return;
    let raf = 0;
    const start = performance.now();
    const tick = (t: number) => {
      const p = Math.min(1, (t - start) / duration);
      const e = 1 - Math.pow(1 - p, 3);
      setVal(from + (target - from) * e);
      if (p < 1) raf = requestAnimationFrame(tick);
      else fromRef.current = target;
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      fromRef.current = target;
    };
  }, [target, duration, reduced]);
  return val;
}

function gradeFor(score: number, target: number, ok: boolean): { g: string; color: string } {
  if (!ok) return { g: "F", color: "var(--abort)" };
  if (target <= 0) return { g: "—", color: "var(--text-mid)" };
  const r = score / target;
  if (r >= 1.3) return { g: "S", color: "var(--caution)" };
  if (r >= 1.08) return { g: "A", color: "var(--go)" };
  if (r >= 0.9) return { g: "B", color: "var(--signal)" };
  if (r >= 0.65) return { g: "C", color: "var(--text-mid)" };
  return { g: "D", color: "var(--abort)" };
}

/* ------------------------------ derivation ------------------------------ */

type D = ReturnType<typeof derive>;
type Check = { id: string; label: string; pass: boolean; detail: string };
type Verdict = { ok: boolean; title: string; body: string };

function derive(state: State) {
  const mission = MISSIONS.find((m) => m.id === state.missionId) ?? null;
  const vehicle = VEHICLES.find((v) => v.id === state.vehicleId) ?? null;
  const orbit = (mission && ORBITS[mission.id].find((o) => o.id === state.orbitId)) || null;
  const power = POWERS.find((p) => p.id === state.powerId) ?? null;
  const insts = INSTRUMENTS.filter((i) => state.instrumentIds.includes(i.id));
  const free = mission?.id === "sandbox";
  const diff = DIFFICULTIES.find((x) => x.id === state.difficulty) ?? DIFFICULTIES[1];
  const roster = state.mode === "coop" ? state.teamMembers : [];
  const crewRoles = Array.from(new Set(roster.map((m) => m.roleId)));

  const instMass = sumOf(insts, (i) => i.mass);
  const instPower = sumOf(insts, (i) => i.power);
  const instCost = sumOf(insts, (i) => i.cost);
  const instData = sumOf(insts, (i) => i.kbps);
  const instScience = sumOf(insts, (i) => i.science);

  const totals = {
    mass: (power?.mass ?? 0) + instMass,
    power: instPower,
    budget: (vehicle?.cost ?? 0) + (orbit?.cost ?? 0) + (power?.cost ?? 0) + instCost,
    data: instData,
  };

  const rawCap = vehicle ? (mission?.regime === "leo" ? vehicle.payloadLEO : vehicle.payloadTLI) : 0;

  const caps = free
    ? { mass: 0, power: 0, budget: 0, data: 0 }
    : {
        mass: Math.round(rawCap * (crewRoles.includes("eng") ? 1.08 : 1) * diff.mass) - (orbit?.reserve ?? 0),
        power: power?.output ?? 0,
        budget: Math.round((mission?.budget ?? 0) * (crewRoles.includes("fd") ? 1.05 : 1) * diff.budget),
        data: Math.round((mission?.downlink ?? 0) * (orbit?.downlinkMod ?? 1) * (crewRoles.includes("comms") ? 1.15 : 1) * diff.data),
      };

  const breach =
    !free &&
    ((!!vehicle && totals.mass > caps.mass) ||
      (!!power && totals.power > caps.power) ||
      (!!mission && totals.budget > caps.budget) ||
      (insts.length > 0 && totals.data > caps.data));

  const enduranceMod = power?.id === "battery" && mission && mission.days > 3 ? 0.4 : 1;
  const mods = {
    orbit: orbit?.scienceMod ?? 1,
    crew: crewRoles.includes("sci") ? 1.1 : 1,
    endurance: enduranceMod,
  };
  const score = Math.round(instScience * mods.orbit * mods.crew * mods.endurance);
  const ready = !!vehicle && !!orbit && !!power && insts.length > 0;

  return {
    mission,
    vehicle,
    orbit,
    power,
    insts,
    crewRoles,
    teamMembers: roster,
    teamName: state.teamName,
    mode: state.mode,
    diff,
    free,
    maxInst: free ? 6 : 2,
    totals,
    caps,
    breach,
    mods,
    baseScience: instScience,
    score,
    ready,
  };
}

/* ownership / locking for co-op */
function canEdit(state: State, section: SectionKey): { lock: string | null; owner: { member: TeamMember; role: CrewMember } | null } {
  const roleId = SECTION_OWNER[section];
  const member = state.teamMembers.find((m) => m.roleId === roleId) ?? null;
  const role = CREW.find((c) => c.id === roleId)!;
  const owner = state.mode === "coop" && member ? { member, role } : null;
  if (state.mode !== "coop" || state.teamMembers.length < 2 || !state.strict || !member) return { lock: null, owner };
  const act = activeMember(state);
  if (act && act.roleId === roleId) return { lock: null, owner };
  return { lock: `Locked — ${role.name} (${member.name}) owns this station. Take their seat or switch off strict roles.`, owner };
}

/* violation helpers (used for disabling + tooltips) */

function violationsForVehicle(state: State, v: Vehicle): string[] {
  const d = derive({ ...state, vehicleId: v.id });
  const out: string[] = [];
  if (!d.mission || d.free) return out;
  if (d.mission.regime === "beyond" && v.payloadTLI === 0) {
    out.push("This vehicle cannot reach trans-lunar / escape trajectories. Select Atlas V or Falcon 9.");
    return out;
  }
  if (d.totals.mass > d.caps.mass) out.push(`Stack mass ${fmtInt(d.totals.mass)} kg exceeds the ${fmtInt(d.caps.mass)} kg capacity for this mission profile.`);
  if (d.totals.budget > d.caps.budget) out.push(`Total cost ${fmtMoney(d.totals.budget)} exceeds the ${fmtMoney(d.caps.budget)} mission budget.`);
  return out;
}

function violationsForOrbit(state: State, o: Orbit): string[] {
  const d = derive({ ...state, orbitId: o.id });
  const out: string[] = [];
  if (!d.mission || d.free) return out;
  if (d.vehicle && d.totals.mass > d.caps.mass) out.push(`Propellant reserve of ${o.reserve} kg leaves only ${fmtInt(d.caps.mass)} kg — your stack is ${fmtInt(d.totals.mass)} kg.`);
  if (d.insts.length > 0 && d.totals.data > d.caps.data) out.push(`Available downlink drops to ${fmtInt(d.caps.data)} kbps on this route — your instruments need ${fmtInt(d.totals.data)} kbps.`);
  if (d.totals.budget > d.caps.budget) out.push(`Total cost ${fmtMoney(d.totals.budget)} exceeds the ${fmtMoney(d.caps.budget)} mission budget.`);
  if (o.id === "sep" && d.power && d.power.id !== "solar") out.push("SEP thrusters draw on solar generation — this route requires the Solar Array power source.");
  return out;
}

function violationsForPower(state: State, p: Power): string[] {
  const d = derive({ ...state, powerId: p.id });
  const out: string[] = [];
  if (!d.mission || d.free) return out;
  if (d.vehicle && d.totals.mass > d.caps.mass) out.push(`Stack mass ${fmtInt(d.totals.mass)} kg exceeds ${fmtInt(d.caps.mass)} kg capacity.`);
  if (d.totals.power > p.output) out.push(`Instruments draw ${fmtInt(d.totals.power)} W — more than this source's ${fmtInt(p.output)} W output.`);
  if (d.totals.budget > d.caps.budget) out.push(`Total cost ${fmtMoney(d.totals.budget)} exceeds the ${fmtMoney(d.caps.budget)} mission budget.`);
  if (d.orbit?.id === "sep" && p.id !== "solar") out.push("Your SEP cruise route requires the Solar Array to power its thrusters.");
  return out;
}

function violationsForInstrument(state: State, i: Instrument): string[] {
  const probe = derive(state);
  const out: string[] = [];
  if (!probe.mission) return out;
  const willAdd = !state.instrumentIds.includes(i.id);
  if (willAdd && state.instrumentIds.length >= probe.maxInst) return [`Instrument bay limited to ${probe.maxInst} payloads.`];
  if (probe.free) return out;
  const ids = willAdd && state.instrumentIds.length < probe.maxInst ? [...state.instrumentIds, i.id] : state.instrumentIds;
  const d = derive({ ...state, instrumentIds: ids });
  if (d.vehicle && d.totals.mass > d.caps.mass) out.push(`Stack mass ${fmtInt(d.totals.mass)} kg exceeds ${fmtInt(d.caps.mass)} kg capacity.`);
  if (d.power && d.totals.power > d.caps.power) out.push(`Instrument draw ${fmtInt(d.totals.power)} W exceeds ${fmtInt(d.caps.power)} W generation.`);
  if (d.totals.budget > d.caps.budget) out.push(`Total cost ${fmtMoney(d.totals.budget)} exceeds the ${fmtMoney(d.caps.budget)} mission budget.`);
  if (d.totals.data > d.caps.data) out.push(`Data rate ${fmtInt(d.totals.data)} kbps exceeds ${fmtInt(d.caps.data)} kbps downlink.`);
  if (willAdd && state.instrumentIds.length >= probe.maxInst) out.push(`Instrument bay limited to ${probe.maxInst} payloads.`);
  return out;
}

/* ------------------------------ simulation ------------------------------ */

const EVENT_POOL: (SimEvent & { when: (d: D) => boolean })[] = [
  { id: "serendipity", text: "SERENDIPITOUS TARGET — the imager catches a fresh impact crater mid-pass.", delta: 60, when: (d) => d.insts.some((i) => i.id === "hsi" || i.id === "hrc") },
  { id: "flare", text: "SOLAR PARTICLE EVENT — array output dips during the storm; ops ride it out.", delta: -25, when: (d) => d.power?.id === "solar" },
  { id: "outage", text: "GROUND STATION OUTAGE — a DSN slot is lost; the buffer holds, some frames drop.", delta: -30, when: (d) => d.caps.data > 0 && d.caps.data - d.totals.data < d.caps.data * 0.15 },
  { id: "window", text: "COMMS OFFICER ON CONSOLE — a hand-picked DSN window recovers the dropped frames.", delta: 35, when: (d) => d.crewRoles.includes("comms") },
  { id: "wheel", text: "MASS MARGIN TIGHT — a reaction wheel runs hot; controllers work around it.", delta: -20, when: (d) => d.caps.mass > 0 && d.caps.mass - d.totals.mass < d.caps.mass * 0.08 },
  { id: "reserve", text: "COST RESERVE HOLDS — unspent funds are reprogrammed into an extended mission.", delta: 45, when: (d) => d.caps.budget > 0 && d.caps.budget - d.totals.budget > d.caps.budget * 0.25 },
  { id: "calibration", text: "CROSS-CALIBRATION — overlapping instrument footprints tighten the combined dataset.", delta: 30, when: (d) => d.insts.length >= 2 },
  { id: "micromet", text: "MICROMETEOROID STRIKE — minor bus damage; operations adapt around it.", delta: -20, when: (d) => d.mission?.id === "asteroid" || d.mission?.id === "lunar" },
  { id: "thermal", text: "THERMAL EXCURSION — a decontamination bake delays first light on the heaviest sensor.", delta: -15, when: (d) => d.insts.some((i) => i.mass > 30) },
  { id: "crew", text: "CREW SYNERGY — Science Lead and Flight Director align on a bonus observation window.", delta: 40, when: (d) => d.crewRoles.includes("sci") && d.crewRoles.includes("fd") },
];

function pickEvents(d: D): SimEvent[] {
  let pool = EVENT_POOL.filter((e) => e.when(d));
  if (d.diff.id === "rookie") pool = pool.filter((e) => e.delta > 0);
  const shuffled = [...pool].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(d.diff.events, shuffled.length)).map(({ id, text, delta }) => ({ id, text, delta }));
}

const SHOCKS: Shock[] = [
  { id: "budgetcut", text: "UNEXPECTED CONSTRAINT — the program office trims the mission budget by 6%.", short: "budget −6%", cap: "budget", mult: 0.94 },
  { id: "massgrowth", text: "UNEXPECTED CONSTRAINT — integration finds 4% mass growth in the bus.", short: "mass capacity −4%", cap: "mass", mult: 0.96 },
  { id: "stationloss", text: "UNEXPECTED CONSTRAINT — a ground station leaves the network; downlink −10%.", short: "downlink −10%", cap: "data", mult: 0.9 },
  { id: "cellfail", text: "UNEXPECTED CONSTRAINT — a power string fails qualification; output −8%.", short: "power −8%", cap: "power", mult: 0.92 },
];

function pickShock(d: D): Shock | null {
  if (d.free) return null;
  if (Math.random() >= d.diff.shock) return null;
  return SHOCKS[Math.floor(Math.random() * SHOCKS.length)];
}
function applyShock(d: D, s: Shock | null): D {
  if (!s) return d;
  const cur = d.caps[s.cap];
  return { ...d, caps: { ...d.caps, [s.cap]: cur > 0 ? Math.round(cur * s.mult) : cur } };
}

function buildChecks(d: D): Check[] {
  if (!d.mission || !d.vehicle || !d.orbit || !d.power) return [];
  const w = d.free;
  return [
    {
      id: "mass",
      label: `Checking stack mass against ${d.vehicle.name} capacity`,
      pass: w || d.totals.mass <= d.caps.mass,
      detail: `${fmtInt(d.totals.mass)} kg required, ${fmtInt(d.caps.mass)} kg available (incl. ${d.orbit.reserve} kg propellant reserve)`,
    },
    {
      id: "power",
      label: "Verifying power generation vs. instrument draw",
      pass: w || d.totals.power <= d.caps.power,
      detail: `${fmtInt(d.totals.power)} W required, ${fmtInt(d.caps.power)} W generated`,
    },
    {
      id: "data",
      label: "Confirming downlink bandwidth",
      pass: w || d.totals.data <= d.caps.data,
      detail: `${fmtInt(d.totals.data)} kbps required, ${fmtInt(d.caps.data)} kbps available`,
    },
    {
      id: "budget",
      label: "Auditing mission budget",
      pass: w || d.totals.budget <= d.caps.budget,
      detail: `${fmtMoney(d.totals.budget)} required, ${fmtMoney(d.caps.budget)} allocated`,
    },
  ];
}

function realityCheck(state: State): string {
  const real = derive({ ...state, missionId: "survey" });
  const checks = buildChecks(real);
  const failed = checks.filter((c) => !c.pass);
  if (checks.length === 0) return "";
  if (failed.length === 0) return " Reality check: against the real Orbital Survey rules this design would have closed on all four constraints.";
  const names: Record<string, string> = { mass: "mass", power: "power", data: "downlink", budget: "budget" };
  return ` Reality check: against the real Orbital Survey rules this design would have breached ${failed.map((c) => names[c.id]).join(", ")} — try it in a scored mission to see how engineers fix that.`;
}

function buildVerdict(d: D, checks: Check[], events: SimEvent[], finalScore: number, shock: Shock | null, state: State): Verdict {
  if (!d.mission || !d.vehicle || !d.orbit || !d.power) {
    return { ok: false, title: "MISSION FAILED", body: "Incomplete design." };
  }
  if (d.free) {
    return {
      ok: true,
      title: "SANDBOX FLIGHT COMPLETE",
      body: `Telemetry nominal for the full ${d.mission.duration.toLowerCase()} campaign — every constraint was waived. Science return: ${fmtInt(finalScore)} points from ${d.insts.length} instrument${d.insts.length === 1 ? "" : "s"}.${realityCheck(state)}`,
    };
  }
  const failed = checks.find((c) => !c.pass);
  const shockNote = shock ? ` An unexpected constraint arrived at launch review (${shock.short}) — a few percent more margin would have absorbed it.` : "";
  if (!failed) {
    const massMargin = Math.round(((d.caps.mass - d.totals.mass) / d.caps.mass) * 100);
    const budgetLeft = Math.round(d.caps.budget - d.totals.budget);
    const targetLine = ` Science return: ${fmtInt(finalScore)} points against a target of ${fmtInt(d.mission.science)}.`;
    const eventLine = events.length > 0 ? ` Along the way, flight dynamics threw ${events.length === 1 ? "you a curveball" : `${events.length} curveballs`} — see the event log.` : " The run was clean — no anomalies.";
    const shockLine = shock ? ` An unexpected constraint (${shock.short}) hit at launch review and your margins absorbed it.` : "";
    return {
      ok: true,
      title: "MISSION SUCCESS",
      body: `Telemetry confirmed through end of prime mission. Your stack closed on all four constraints with ${massMargin}% mass margin and ${fmtMoney(budgetLeft)} of budget unspent — the kind of margin real review boards fight for. The architecture echoes flight-proven designs: ${d.mission.analogues}.${shockLine}${eventLine}${targetLine}`,
    };
  }

  const heaviest = [...d.insts].sort((a, b) => b.mass - a.mass)[0];
  const hungriest = [...d.insts].sort((a, b) => b.power - a.power)[0];
  const loudest = [...d.insts].sort((a, b) => b.kbps - a.kbps)[0];
  const priciest = [...d.insts].sort((a, b) => b.cost - a.cost)[0];

  const bodies: Record<string, string> = {
    mass: `Your stack weighs ${fmtInt(d.totals.mass)} kg, but ${d.vehicle.name} on this mission profile offers only ${fmtInt(d.caps.mass)} kg after the ${d.orbit.name} propellant reserve. Swap to a higher-capacity vehicle, choose a route with a smaller reserve, or drop the ${heaviest?.name ?? "heaviest instrument"} (${heaviest?.mass ?? 0} kg) for a lighter sensor.`,
    power: `Your instruments draw ${fmtInt(d.totals.power)} W, but the ${d.power.name} generates only ${fmtInt(d.caps.power)} W. Select the Solar Array (1,420 W), or trade the ${hungriest?.name ?? "highest-draw instrument"} (${hungriest?.power ?? 0} W) for a lower-power sensor.`,
    data: `The ${loudest?.name ?? "top data-rate instrument"} generates more data than your downlink can carry home — ${fmtInt(d.totals.data)} kbps required against ${fmtInt(d.caps.data)} kbps available on the ${d.orbit.name} route. Pick an orbit with more ground-station contact, bring a Comms Officer on console, or swap it for a lower-rate instrument like the Fluxgate Magnetometer (2 kbps).`,
    budget: `The full stack costs ${fmtMoney(d.totals.budget)} against a ${fmtMoney(d.caps.budget)} budget. Drop to a cheaper launch vehicle, choose a lower-cost route, or trade the ${priciest?.name ?? "priciest instrument"} (${fmtMoney(priciest?.cost ?? 0)}) for a lighter sensor.`,
  };

  return { ok: false, title: "MISSION FAILED", body: (bodies[failed.id] ?? "Design did not close.") + shockNote };
}

/* best feasible design under the current rules (for post-mission analysis) */
function findBest(state: State) {
  const mission = MISSIONS.find((m) => m.id === state.missionId);
  if (!mission || mission.id === "sandbox") return null;
  const combos: Instrument[][] = [];
  INSTRUMENTS.forEach((a, i) => {
    combos.push([a]);
    for (let j = i + 1; j < INSTRUMENTS.length; j++) combos.push([a, INSTRUMENTS[j]]);
  });
  let best: null | { score: number; vehicle: Vehicle; orbit: Orbit; power: Power; insts: Instrument[] } = null;
  for (const v of VEHICLES) {
    for (const o of ORBITS[mission.id]) {
      for (const p of POWERS) {
        if (o.id === "sep" && p.id !== "solar") continue;
        for (const c of combos) {
          const d = derive({ ...state, vehicleId: v.id, orbitId: o.id, powerId: p.id, instrumentIds: c.map((i) => i.id) });
          if (d.breach) continue;
          if (!best || d.score > best.score) best = { score: d.score, vehicle: v, orbit: o, power: p, insts: c };
        }
      }
    }
  }
  return best;
}

type Insight = { tone: "good" | "warn" | "info"; text: string };

function buildInsights(d: D, events: SimEvent[], shock: Shock | null, finalScore: number, best: ReturnType<typeof findBest>): Insight[] {
  const out: Insight[] = [];
  if (!d.mission) return out;
  if (!d.free) {
    const margins: [string, number][] = [
      ["payload mass", d.caps.mass > 0 ? (d.caps.mass - d.totals.mass) / d.caps.mass : 1],
      ["power", d.caps.power > 0 ? (d.caps.power - d.totals.power) / d.caps.power : 1],
      ["budget", d.caps.budget > 0 ? (d.caps.budget - d.totals.budget) / d.caps.budget : 1],
      ["downlink", d.caps.data > 0 ? (d.caps.data - d.totals.data) / d.caps.data : 1],
    ];
    const tight = [...margins].sort((a, b) => a[1] - b[1])[0];
    const pct = Math.round(tight[1] * 100);
    out.push(
      tight[1] < 0.1
        ? { tone: "warn", text: `Your tightest constraint was ${tight[0]} at ${pct}% margin — it closed, but any growth would have broken the design.` }
        : { tone: "good", text: `Your tightest constraint (${tight[0]}) still carried ${pct}% margin — comfortable headroom against surprises.` }
    );
  }
  if (d.orbit && d.orbit.scienceMod !== 1) {
    out.push({
      tone: d.orbit.scienceMod > 1 ? "good" : "info",
      text: `The ${d.orbit.name} route multiplied science by ×${d.orbit.scienceMod.toFixed(1)}${d.orbit.scienceMod > 1 ? " — a better vantage than baseline." : " — the geometry cost you some return."}`,
    });
  }
  if (d.power?.id === "battery" && d.mission.days > 3) {
    out.push({ tone: "warn", text: `The Battery Bank has 72 h of endurance but this mission runs ${d.mission.duration.toLowerCase()}. The spacecraft went dark early and science was cut to 40%.` });
  }
  if (d.mode === "coop") {
    const missing = CREW.filter((c) => !d.crewRoles.includes(c.id));
    if (missing.length > 0 && d.crewRoles.length > 0) {
      out.push({ tone: "info", text: `Roles not staffed: ${missing.map((m) => m.name).join(", ")}. Their perks (${missing.map((m) => m.perk.split(" — ")[1]?.replace(" while on console.", "") ?? "").join("; ")}) were left on the table.` });
    } else if (missing.length === 0) {
      out.push({ tone: "good", text: "Full crew on console — every specialist perk was active for this flight." });
    }
  }
  const net = sumOf(events, (e) => e.delta);
  if (events.length > 0) {
    out.push({ tone: net >= 0 ? "good" : "info", text: `Flight events netted ${net >= 0 ? "+" : ""}${net} points across ${events.length} anomal${events.length === 1 ? "y" : "ies"}.` });
  }
  if (shock) out.push({ tone: "info", text: `An unexpected constraint (${shock.short}) hit at launch review. Your margins absorbed it.` });
  if (!d.free && d.caps.budget > 0) {
    const left = d.caps.budget - d.totals.budget;
    if (left > d.caps.budget * 0.25) out.push({ tone: "info", text: `${fmtMoney(Math.round(left))} of budget went unspent — enough headroom to afford a heavier launcher or a pricier instrument.` });
  }
  if (best) {
    const ratio = finalScore / Math.max(1, best.score);
    out.push({
      tone: ratio >= 0.95 ? "good" : "info",
      text: `The best feasible design under these rules scores ${fmtInt(best.score)}; yours reached ${Math.round(ratio * 100)}% of that${ratio >= 0.95 ? " — essentially optimal." : "."}`,
    });
  }
  return out;
}

/* ------------------------------ telemetry model ------------------------------ */

const PHASES: Record<string, { name: string; end: number }[]> = {
  survey: [
    { name: "LAUNCH & EARLY ORBIT", end: 0.04 },
    { name: "COMMISSIONING", end: 0.14 },
    { name: "PRIME SCIENCE", end: 0.92 },
    { name: "EXTENDED OPS", end: 1 },
  ],
  lunar: [
    { name: "LAUNCH", end: 0.05 },
    { name: "TRANS-LUNAR COAST", end: 0.35 },
    { name: "ORBIT & DESCENT", end: 0.55 },
    { name: "SURFACE SCIENCE", end: 1 },
  ],
  asteroid: [
    { name: "LAUNCH", end: 0.02 },
    { name: "CRUISE", end: 0.55 },
    { name: "RENDEZVOUS", end: 0.65 },
    { name: "PROXIMITY OPS", end: 1 },
  ],
};
const DUTY: Record<string, number[]> = {
  survey: [0, 0.2, 1, 0.7],
  lunar: [0, 0.1, 0.5, 1],
  asteroid: [0, 0.1, 0.3, 1],
};

type Tel = {
  n: number;
  gen: number[];
  draw: number[];
  data: number[];
  cost: number[];
  prop: number[];
  phases: { name: string; end: number }[];
  days: number;
};

function buildTelemetry(d: D): Tel | null {
  if (!d.mission || !d.power || !d.vehicle || !d.orbit) return null;
  const key = d.mission.id === "sandbox" ? "survey" : d.mission.id;
  const phases = PHASES[key];
  const duty = DUTY[key];
  const days = d.mission.days;
  const yrs = days / 365;
  const secs = days * 86400;
  const N = 96;
  const gen: number[] = [];
  const draw: number[] = [];
  const data: number[] = [];
  const cost: number[] = [];
  const prop: number[] = [];
  const build = d.vehicle.cost + d.power.cost + sumOf(d.insts, (i) => i.cost);
  const eclipse = key === "survey" || d.orbit.id === "llo";
  let cum = 0;
  for (let i = 0; i < N; i++) {
    const t = i / (N - 1);
    const pi = phases.findIndex((p) => t <= p.end);
    const ph = pi < 0 ? phases.length - 1 : pi;
    let g = d.power.output;
    if (d.power.id === "solar") {
      g *= 1 - 0.02 * yrs * t;
      if (eclipse) g *= 1 - 0.3 * Math.pow(Math.max(0, Math.sin(t * Math.PI * 2 * 14)), 2);
    } else if (d.power.id === "rtg") {
      g *= 1 - 0.04 * yrs * t;
    } else {
      g *= Math.max(0, 1 - (t * days * 24) / 72);
    }
    const alive = d.power.id === "battery" ? g > 1 : true;
    const thr = d.orbit.id === "sep" && ph === 1 ? 520 : 0;
    const dr = alive ? d.totals.power * duty[ph] + thr : 0;
    gen.push(g);
    draw.push(dr);
    const rate = alive ? d.totals.data * duty[ph] * 0.4 * 125 : 0; // bytes / s
    cum += (rate * (secs / N)) / 1e9;
    data.push(cum);
    cost.push(build * smooth(t / 0.04) + d.orbit.cost * t);
    let frac: number;
    if (d.orbit.id === "sep") frac = 1 - 0.85 * smooth(t / phases[2].end);
    else
      frac =
        1 -
        (0.3 * smooth((t - phases[0].end + 0.02) / 0.03) +
          0.3 * smooth((t - phases[1].end + 0.02) / 0.03) +
          0.2 * smooth((t - phases[2].end + 0.02) / 0.03));
    prop.push(Math.max(0, d.orbit.reserve * frac));
  }
  return { n: N, gen, draw, data, cost, prop, phases, days };
}

/* ------------------------------ 3D helpers ------------------------------ */

function ringPts(a: number, b: number, cx: number, tiltX: number, tiltZ: number, n = 160): V3[] {
  const e = new THREE.Euler(tiltX, 0, tiltZ);
  const out: V3[] = [];
  for (let i = 0; i <= n; i++) {
    const th = (i / n) * Math.PI * 2;
    const v = new THREE.Vector3(Math.cos(th) * a + cx, 0, Math.sin(th) * b).applyEuler(e);
    out.push([v.x, v.y, v.z]);
  }
  return out;
}
function pointOnEllipse(a: number, b: number, cx: number, th: number, tiltX: number, tiltZ: number): V3 {
  const e = new THREE.Euler(tiltX, 0, tiltZ);
  const v = new THREE.Vector3(Math.cos(th) * a + cx, 0, Math.sin(th) * b).applyEuler(e);
  return [v.x, v.y, v.z];
}
function spiralPts(r0: number, r1: number, turns: number, n: number, tilt: number): V3[] {
  const e = new THREE.Euler(tilt, 0, 0);
  const out: V3[] = [];
  for (let i = 0; i <= n; i++) {
    const u = i / n;
    const r = r0 + (r1 - r0) * u;
    const th = u * turns * Math.PI * 2;
    const v = new THREE.Vector3(Math.cos(th) * r, 0, Math.sin(th) * r).applyEuler(e);
    out.push([v.x, v.y, v.z]);
  }
  return out;
}
function bezierPts(p0: V3, p2: V3, lift: number, n: number): V3[] {
  const p1: V3 = [((p0[0] + p2[0]) / 2) * 1.25, lift, ((p0[2] + p2[2]) / 2) * 1.25];
  const out: V3[] = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const a = (1 - t) * (1 - t);
    const b = 2 * (1 - t) * t;
    const c = t * t;
    out.push([a * p0[0] + b * p1[0] + c * p2[0], a * p0[1] + b * p1[1] + c * p2[1], a * p0[2] + b * p1[2] + c * p2[2]]);
  }
  return out;
}

function trajectoryFor(missionId: string) {
  const key = missionId === "sandbox" ? "survey" : missionId;
  const paths: { id: string; pts: V3[] }[] = [];
  const rings: V3[][] = [];
  const extras: { earth?: V3; asteroid?: V3 } = {};
  const central: "earth" | "moon" | "sun" = key === "survey" ? "earth" : key === "lunar" ? "moon" : "sun";
  if (key === "survey") {
    paths.push({ id: "leo400", pts: ringPts(1.38, 1.38, 0, 0.9, 0) });
    paths.push({ id: "sso600", pts: ringPts(1.58, 1.58, 0, Math.PI / 2 - 0.17, 0) });
    paths.push({ id: "elliptical", pts: ringPts(1.9, 1.766, -0.7, 0.5, 0.25) });
  } else if (key === "lunar") {
    paths.push({ id: "direct", pts: spiralPts(3.6, 1.03, 1.4, 140, 0.35) });
    paths.push({ id: "llo", pts: ringPts(1.35, 1.35, 0, Math.PI / 2 - 0.1, 0) });
    paths.push({ id: "elo", pts: ringPts(2.2, 1.96, -1.0, Math.PI / 2 - 0.1, 0.2) });
  } else {
    const ac = 0.9;
    const aa = 3.4;
    const ab = Math.sqrt(aa * aa - ac * ac);
    const astPt = pointOnEllipse(aa, ab, -ac, 2.3, 0.15, 0);
    const earthPt: V3 = [2, 0, 0];
    rings.push(ringPts(2, 2, 0, 0, 0));
    rings.push(ringPts(aa, ab, -ac, 0.15, 0));
    paths.push({ id: "directIP", pts: bezierPts(earthPt, astPt, 0.9, 140) });
    paths.push({ id: "ega", pts: [...ringPts(2, 2, 0, 0, 0), ...bezierPts(earthPt, astPt, 1.5, 140)] });
    paths.push({ id: "sep", pts: spiralPts(2, 3.3, 1.25, 160, 0.1) });
    extras.earth = earthPt;
    extras.asteroid = astPt;
  }
  return { central, paths, rings, extras };
}

